{"path": "zipper.py", "content": "class Zipper:
    """Zipper over a binary tree of dicts: {"value": v, "left": t|None, "right": t|None}."""

    def __init__(self, tree, path):
        # path: list of (direction, parent_value, other_subtree), innermost last
        self._tree = tree
        self._path = path

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self._tree["value"]

    def set_value(self, value):
        return Zipper(
            {"value": value, "left": self._tree["left"], "right": self._tree["right"]},
            self._path,
        )

    def left(self):
        child = self._tree["left"]
        if child is None:
            return None
        crumb = ("left", self._tree["value"], self._tree["right"])
        return Zipper(child, self._path + [crumb])

    def set_left(self, tree):
        return Zipper(
            {"value": self._tree["value"], "left": tree, "right": self._tree["right"]},
            self._path,
        )

    def right(self):
        child = self._tree["right"]
        if child is None:
            return None
        crumb = ("right", self._tree["value"], self._tree["left"])
        return Zipper(child, self._path + [crumb])

    def set_right(self, tree):
        return Zipper(
            {"value": self._tree["value"], "left": self._tree["left"], "right": tree},
            self._path,
        )

    def up(self):
        if not self._path:
            return None
        direction, value, other = self._path[-1]
        if direction == "left":
            parent = {"value": value, "left": self._tree, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._tree}
        return Zipper(parent, self._path[:-1])

    def to_tree(self):
        zipper = self
        while zipper._path:
            zipper = zipper.up()
        return zipper._tree

    def __eq__(self, other):
        if not isinstance(other, Zipper):
            return NotImplemented
        return self._tree == other._tree and self._path == other._path
